mapper.select:
select count(*)
from practice_generated_content
where owner_key = #{ownerKey}
  and owner_key_version = #{ownerKeyVersion}
  and surface = #{surface}
  and mode = #{mode}
  and generation_started_at >= #{dailyFrom,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}

mapper.update:
update practice_generated_content
set status = 'generating',
    generation_started_at = #{updatedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler},
    updated_at = #{updatedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
where generated_content_id = #{generatedContentId}
  and status = 'draft'

mapper.delete:
delete from practice_generated_content
where generated_content_id = #{generatedContentId}
  and owner_key_version = #{ownerKeyVersion}
  and owner_scope = 'installation'
  and status = 'active'
  and retention_expires_at <= #{dueAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}

mapper.update:
update practice_generated_content
set status = 'rejected', generation_error_code = #{errorCode},
    generation_error_retryable = #{retryable}, normalized_scene_text = null,
    retention_expires_at = case when owner_scope = 'installation'
        then #{retentionExpiresAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
        else null end,
    updated_at = #{updatedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
where generated_content_id = #{generatedContentId}
  and status in ('draft', 'generating')

update practice_generated_content
set status = 'expired', generation_error_code = #{errorCode},
    generation_error_retryable = #{retryable}, normalized_scene_text = null,
    generation_expires_at = #{updatedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler},
    retention_expires_at = case when owner_scope = 'installation'
        then #{retentionExpiresAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
        else null end,
    updated_at = #{updatedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
where generated_content_id = #{generatedContentId}
  and status in ('draft', 'generating')

with candidates as (
    select generated_content_id
    from practice_generated_content
    where status in ('draft', 'generating')
      and generation_expires_at <= #{interruptedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
    order by generation_expires_at, generated_content_id
    limit #{limit}
    for update skip locked
)
update practice_ai_provider_calls calls
set outcome = 'interrupted', completed_at = #{interruptedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
from practice_ai_operation_runs operations,
     candidates
where calls.completed_at is null
  and calls.operation_run_id = operations.operation_run_id
  and operations.generated_content_id = candidates.generated_content_id

with candidates as (
    select generated_content_id
    from practice_generated_content
    where status in ('draft', 'generating')
      and generation_expires_at <= #{interruptedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
    order by generation_expires_at, generated_content_id
    limit #{limit}
    for update skip locked
)
update practice_generated_content target
set status = 'expired', generation_error_code = 'generation_interrupted',
    generation_error_retryable = true, normalized_scene_text = null,
    retention_expires_at = case when target.owner_scope = 'installation'
        then #{installationRetentionExpiresAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
        else null end,
    updated_at = #{interruptedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
from candidates
where target.generated_content_id = candidates.generated_content_id
  and target.status in ('draft', 'generating')

mapper.delete:
delete from practice_generated_content
where generated_content_id in (
    select generated_content_id from practice_generated_content
    where owner_scope = 'installation'
      and status in ('active', 'expired', 'rejected')
      and retention_expires_at <= #{retentionExpiresAtOrBefore,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
    order by retention_expires_at, generated_content_id
    limit #{limit}
    for update skip locked
)

delete from practice_generated_content
where account_id = #{accountId}
  and owner_scope in ('account', 'profile')
